changeSet.sql:
DO $$
DECLARE
    r RECORD;
BEGIN
    -- 1. Supprimer toutes les contraintes de type CHECK mentionnant 'genre' sur la table 'users'
    FOR r IN (
        SELECT c.conname
        FROM pg_constraint c
        JOIN pg_class t ON c.conrelid = t.oid
        WHERE t.relname = 'users'
          AND c.contype = 'c'
          AND pg_get_constraintdef(c.oid) ILIKE '%genre%'
    ) LOOP
        EXECUTE 'ALTER TABLE users DROP CONSTRAINT IF EXISTS ' || quote_ident(r.conname);
    END LOOP;

    -- Supprimer explicitement par les noms usuels par sécurité
    EXECUTE 'ALTER TABLE users DROP CONSTRAINT IF EXISTS users_genre_check';
    EXECUTE 'ALTER TABLE users DROP CONSTRAINT IF EXISTS users_genre_check1';
    EXECUTE 'ALTER TABLE users DROP CONSTRAINT IF EXISTS check_users_genre';

    -- 2. Convertir la colonne genre en VARCHAR(20) si elle n'est pas déjà en varchar/text
    IF EXISTS (
        SELECT 1 
        FROM information_schema.columns 
        WHERE table_name = 'users' AND column_name = 'genre' AND data_type NOT IN ('character varying', 'text')
    ) THEN
        ALTER TABLE users ALTER COLUMN genre TYPE VARCHAR(20) USING (
            CASE 
                WHEN genre::text = '0' THEN 'HOMME' 
                WHEN genre::text = '1' THEN 'FEMME' 
                WHEN genre::text ILIKE 'femme' THEN 'FEMME'
                WHEN genre::text ILIKE 'homme' THEN 'HOMME'
                ELSE 'HOMME'
            END
        );
    END IF;

    -- 3. Définir la valeur par défaut pour les futures créations
    ALTER TABLE users ALTER COLUMN genre SET DEFAULT 'HOMME';
END $$;
